(* [comment removed for export] *)
Lemma sgn_set a s : 0 <= a < 256 -> s = 0 \/ s = 2 ->
  0 <= Z.lor (Z.land a 253) s < 256 /\ Z.land (Z.lor (Z.land a 253) s) 2 = s /\ Z.testbit (Z.lor (Z.land a 253) s) 0 = Z.testbit a 0.
