Lemma BLKP D1 (INC1 : incl D D1) BX1 Aw1 cr1 M1 model1 LK1 (Ma Mb : mem) (Wp : Z -> Prop) q :
  GM [D1] BX1 M1 model1 LK1 Aw1 cr1 -> In (q, 64) (BX1 ++ LBX) ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ Wp a -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)) ->
  (forall a, Wp a -> (spc <= a < sp) \/ (F <= a < F + 256) \/ (F / 8 + SB <= a < F / 8 + SB + 32) \/ (xo <= a < xo + 32)) ->
  PMFA.agA Ma Mb q 64.
