Lemma kept_binl (Wx : Z -> Prop) (Ma Mb : mem) y fby (len : nat) w0 w1 : kept Wx Ma Mb ->
  ((F + 32 <= y /\ y + 32 <= F + 248) \/ y = xo) -> (forall a, y <= a < y + 32 -> ~ Wx a) -> 0 <= y -> y + 32 <= 2 ^ 64 ->
