Ltac lows := pose proof (OLOW xo AO O8) as LOo.
Definition wc_okW (Wc : list L5.range) : Prop :=
  forall q, In q Wc -> (exists k, 32 <= k /\ k + 32 <= 248 /\ q = (F + k, 32)) \/ q = (xo, 32)
                       \/ (exists lo n, 0 <= lo /\ 0 < n /\ lo + n <= 56 /\ q = (spc + lo, n)).
(* [comment removed for export] *)
Lemma AFTERW D1 (INC1 : incl D D1) BX1 Aw1 cr1 BX4 Aw4 cr4 (Wc : list L5.range) M3 model3 LK3 (M4 : mem) model4 LK4 hc :
  GM [D1] BX1 M3 model3 LK3 Aw1 cr1 -> 0 <= hc -> hc + 1 <= NETSA.TOB_H -> wc_okW Wc ->
  L5CA.ahpres L ar (BX1 ++ LBX) FF' spc (PMSPA.pm_scr hc) Wc M3 M4 ->
  ri_inv (HIk D1) (BX4 ++ LBX) FF' LK4 cr4 Aw4 M4 (vml_of model4) -> L5CA.amodel_ok Aw4 model4 -> model_rt model3 model4 -> incl Aw1 Aw4 -> incl LK4 LK3 ->
  GM [D1] BX4 M4 model4 LK4 Aw4 cr4
  /\ (forall a, spc <= a < sp -> L5.outside Wc a -> M4 (Z_to_bv 64 a) = M3 (Z_to_bv 64 a))
  /\ (forall a, F / 8 + 2147450880 <= a < F / 8 + 2147450880 + 32 -> M4 (Z_to_bv 64 a) = M3 (Z_to_bv 64 a))
  /\ (forall a, (F + 32 <= a < F + 248) \/ (xo <= a < xo + 32) -> L5.outside Wc a -> M4 (Z_to_bv 64 a) = M3 (Z_to_bv 64 a)).
Proof.
