Definition keptS (lo n : Z) (Wx : Z -> Prop) (Ma Mb : mem) : Prop :=
  (forall a, spc <= a < sp -> ~ (spc + lo <= a < spc + lo + n) -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a))
  /\ (forall a, F / 8 + 2147450880 <= a < F / 8 + 2147450880 + 32 -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a))
  /\ (forall a, (F + 32 <= a < F + 248) \/ (xo <= a < xo + 32) -> ~ Wx a -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)).
Lemma keptS_binl lo n (Wx : Z -> Prop) (Ma Mb : mem) y fby (len : nat) w0 w1 : keptS lo n Wx Ma Mb ->
  ((F + 32 <= y /\ y + 32 <= F + 248) \/ y = xo) -> (forall a, y <= a < y + 32 -> ~ Wx a) -> 0 <= y -> y + 32 <= 2 ^ 64 ->
