Lemma BDY_K D1 (INC1 : incl D D1) BX1 Aw1 cr1 M1 model1 LK1 (Ma Mb : mem) (Wx : Z -> Prop) s fbx (len : nat) q w0 w1 :
  GM [D1] BX1 M1 model1 LK1 Aw1 cr1 -> In (q, 64) (BX1 ++ LBX) -> kept Wx Ma Mb ->
  ((F + 32 <= s /\ s + 32 <= F + 248) \/ s = xo \/ (spc <= s /\ s + 32 <= sp)) -> (forall a, s <= a < s + 32 -> ~ Wx a) ->
  PMFA.agA Ma Mb q 64 -> PQATSW2.bdyn_at RSEGS Ma s fbx len q w0 w1 -> PQATSW2.bdyn_at RSEGS Mb s fbx len q w0 w1.
Proof.
