Definition bregs (Rx : bvmap 5 word) : Prop :=
  getr Rx (reg 2) = Z_to_bv 64 spc /\ getr Rx (reg 3) = getr R (reg 3) /\ getr Rx (reg 4) = getr R (reg 4) /\ getr Rx (reg 8) = Z_to_bv 64 sp
  /\ getr Rx (reg 9) = Z_to_bv 64 spc /\ getr Rx (reg 21) = Z_to_bv 64 (F / 8 + SBL) /\ getr Rx (reg 26) = Z_to_bv 64 SBL /\ getr Rx (reg 27) = Z_to_bv 64 F.
Definition BRL : list nat := [2; 3; 4; 8; 9; 21; 26; 27]%nat.
