(* [comment removed for export] *)
Definition XPOST (Mx : mem) (rc : Z) : Prop :=
  (rc = 0 /\ exists fbx x0 x1, PQATSS.binl_at RSEGS Mx xo fbx (PQATSS.wlen x0 x1) x0 x1 /\ Z.testbit fbx 0 = false) \/ (rc = 22 /\ PQATSS.binl_at RSEGS Mx xo 0 0%nat 0 0).
