(* [comment removed for export] *)
Lemma TDD (gk : list Z) (cr1 : credit) (p : Z) Aw6 M6 model6 LK6 (fx6 : FPState) R6 (rc resptr fbT : Z) :
  In gk GKEYS -> PMSP.credit_keep cr cr1 (PQATSG.gcostD L gk D 64) PMSP.cr0 ->
  GM [gk :: D] [(p, 64)] M6 model6 LK6 Aw6 cr1 -> XPOST M6 rc -> cells [(spc + 24, F)] M6 ->
  L5.u8_at RSEGS M6 (F + 96) fbT -> 0 <= fbT < 256 -> Z.testbit fbT 0 = true -> L5.u64_at RSEGS M6 (F + 120) p -> L5.u64_at RSEGS M6 (F + 112) 8 ->
  tregs R6 resptr rc -> 0 <= resptr <= 2 ^ 47 -> (rc = 0 \/ rc = 22) ->
