Inductive tstate : Type := TI (w0 w1 : Z) | TD (p w0 w1 : Z) (gk : list Z) (cr1 : credit).
Definition st_bx (st : tstate) : list (Z * Z) := match st with TI _ _ => [] | TD p _ _ _ _ => [(p, 64)] end.
Definition st_D (st : tstate) : list (list Z) := match st with TI _ _ => D | TD _ _ _ gk _ => gk :: D end.
Definition st_cr (st : tstate) : credit := match st with TI _ _ => cr | TD _ _ _ _ cr1 => cr1 end.
Definition st_val (st : tstate) : Z := match st with TI w0 w1 => w0 + 2 ^ 64 * w1 | TD _ w0 w1 _ _ => w0 + 2 ^ 64 * w1 end.
