(* [comment removed for export] *)
Definition TDF (p : Z) (gk : list Z) (cr1 : credit) : Prop :=
  In gk GKEYS /\ PMSP.credit_keep cr cr1 (PQATSG.gcostD L gk D 64) PMSP.cr0 /\ ablock_range L ar p 64 /\ blocks_apart p 64 (BX0 ++ LBX) /\ fframes_apart p 64 FF'.
Definition st_okF (Mx : mem) (st : tstate) (fb : Z) : Prop :=
  match st with
  | TI w0 w1 => PQATSS.binl_at RSEGS Mx (F + 96) fb (PQATSS.wlen w0 w1) w0 w1
  | TD p w0 w1 gk cr1 => PQATSW2.bdyn_at RSEGS Mx (F + 96) fb 2%nat p w0 w1 /\ 1 <= w1 /\ TDF p gk cr1
  end.
Definition st_fb (st : tstate) : Z := match st with TI _ _ => 0 | TD _ _ _ _ _ => 1 end.
Definition st_ok (Mx : mem) (st : tstate) : Prop := st_okF Mx st (st_fb st).
(* [comment removed for export] *)
Lemma st_flags (Mx : mem) st fb : st_okF Mx st fb ->
  L5.u8_at RSEGS Mx (F + 96) fb /\ 0 <= fb < 256 /\ Z.testbit fb 0 = (match st with TI _ _ => false | TD _ _ _ _ _ => true end).
Proof.
