Definition lregs (Rx : bvmap 5 word) : Prop :=
  bregs Rx /\ getr Rx (reg 18) = Z_to_bv 64 9 /\ getr Rx (reg 19) = Z_to_bv 64 (sa + nn) /\ getr Rx (reg 23) = Z_to_bv 64 (F + 96).
Definition LRL : list nat := [2; 3; 4; 8; 9; 21; 26; 27; 18; 19; 23]%nat.
