(* [comment removed for export] *)
Lemma SBYTE D1 (INC1 : incl D D1) BX1 Aw1 cr1 M1 model1 LK1 c : GM [D1] BX1 M1 model1 LK1 Aw1 cr1 -> sa <= c < sa + nn ->
  let MV := mrestrict (ahid Aw1 model1) M1 in
  (exists b, L5.u8_at RSEGS MV c b /\ 0 <= b < 256)
  /\ (exists kk, rdn RSEGS MV (Z_to_bv 64 (c / 8 + SBL)) 1%nat = Some [Z_to_bv 8 kk] /\ (kk = 0 \/ (1 <= kk <= 7 /\ c mod 8 < kk))).
Proof.
