(* [comment removed for export] *)
Section Arith.
Variables (PC : Z) (yv : Z) (op : Z -> Z).
Hypothesis OPmono : forall V, 2 ^ 64 <= V -> 2 ^ 64 <= op V.
Hypothesis OPbnd : forall V, 0 <= V < 10 ^ 31 -> 0 <= op V < 2 ^ 128.
(* [comment removed for export] *)
Hypothesis CI : forall D0 (fx : FPState) (R : bvmap 5 word) (Mx : mem) (model : Model) (Kx : TSet) (LB : list (Z * Z)) (FFx LK : list fframe) (Aw : list (Z * Z)) (crx : credit)
    (spx rx o fb : Z) (len : nat) (v0 : Z),
    ri_inv (HIk D0) LB FFx LK crx Aw Mx (vml_of model) -> L5CA.amodel_ok Aw model -> Kx [] ->
    PMSPA.entryA AD L ar R Mx spx rx NETSA.MUL10_H -> PGSA.ffroomB PQRA.FCM NETSA.MUL10_H FFx LK -> PMSPA.ffrsA FFx spx -> spx mod 16 = 0 ->
    getr R (reg 10) = Z_to_bv 64 o -> getr R (reg 11) = Z_to_bv 64 yv ->
    PMSPA.aobjA FFx o 32 -> o mod 8 = 0 -> PMSPA.accA Mx o 32 ->
    PQATSS.binl_at RSEGS Mx o fb len v0 0 -> (len <= 1)%nat -> (len = 0%nat -> v0 = 0) -> Z.testbit fb 1 = false ->
    PMSTA.base_okA RSEGS AD Mx ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (w0 w1 : Z),
        regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 o ->
        w0 + 2 ^ 64 * w1 = op v0 -> PQATSS.binl_at RSEGS M' o fb (PQATSS.wlen w0 w1) w0 w1 ->
        L5CA.ahpres L ar LB FFx spx (PMSPA.pm_scr NETSA.MUL10_H) [(o, 32)] Mx M' ->
        model_rt model model' -> incl LK' LK -> L5CA.amodel_ok Aw model' ->
        ri_inv (HIk D0) LB FFx LK' crx Aw M' (vml_of model') ->
        srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx' R' rx M' model') Kx) ->
    srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx R PC Mx model) Kx.
Hypothesis CG : forall (fx : FPState) (R : bvmap 5 word) (Mx : mem) (model : Model) (Kx : TSet) (LB : list (Z * Z)) (FFx LK : list fframe) (Aw : list (Z * Z)) (crx : credit)
    (spx rx o fb v0 v1 : Z) (D0 : list (list Z)),
    ri_inv (HIk D0) LB FFx LK crx Aw Mx (vml_of model) -> L5CA.amodel_ok Aw model -> Kx [] ->
    PMSPA.entryA AD L ar R Mx spx rx NETSA.MUL10_H -> PGSA.ffroomB PQRA.FCM NETSA.MUL10_H FFx LK -> PMSPA.ffrsA FFx spx -> spx mod 16 = 0 ->
    getr R (reg 10) = Z_to_bv 64 o -> getr R (reg 11) = Z_to_bv 64 yv ->
    PMSPA.aobjA FFx o 32 -> o mod 8 = 0 -> PMSPA.accA Mx o 32 ->
    PQATSS.binl_at RSEGS Mx o fb 2%nat v0 v1 -> Z.testbit fb 1 = false -> 1 <= v1 -> op (v0 + 2 ^ 64 * v1) < 2 ^ 128 ->
    PMSTA.base_okA RSEGS AD Mx ->
    PQATSG.gpre L LR PQATSG.OPNEW_RA_A D0 64 crx ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (cr' : credit) (p w0 w1 : Z) (gk : list Z),
        regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 o -> In gk (PQATSG.GKEYS LR PQATSG.OPNEW_RA_A) ->
        w0 + 2 ^ 64 * w1 = op (v0 + 2 ^ 64 * v1) -> PQATSW2.bdyn_at RSEGS M' o (Z.lor fb 1) 2%nat p w0 w1 ->
        L5CA.afresh L ar LB (FFx ++ LK') M' p 64 ->
        L5CA.ahpres L ar LB FFx spx (PMSPA.pm_scr NETSA.MUL10_H) [(o, 32)] Mx M' ->
        PMSP.credit_keep crx cr' (PQATSG.gcostD L gk D0 64) PMSP.cr0 ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv (HIk (gk :: D0)) ((p, 64) :: LB) FFx LK' cr' Aw' M' (vml_of model') ->
        srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx' R' rx M' model') Kx) ->
    srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx R PC Mx model) Kx.
Hypothesis CD : forall D0 (fx : FPState) (R : bvmap 5 word) (Mx : mem) (model : Model) (Kx : TSet) (LB : list (Z * Z)) (FFx LK : list fframe) (Aw : list (Z * Z)) (crx : credit)
    (spx rx o fb p v0 v1 : Z),
    ri_inv (HIk D0) LB FFx LK crx Aw Mx (vml_of model) -> L5CA.amodel_ok Aw model -> Kx [] ->
    PMSPA.entryA AD L ar R Mx spx rx NETSA.MUL10_H -> PGSA.ffroomB PQRA.FCM NETSA.MUL10_H FFx LK -> PMSPA.ffrsA FFx spx -> spx mod 16 = 0 ->
    getr R (reg 10) = Z_to_bv 64 o -> getr R (reg 11) = Z_to_bv 64 yv ->
    PMSPA.aobjA FFx o 32 -> o mod 8 = 0 -> PMSPA.accA Mx o 32 ->
    PQATSW2.bdyn_at RSEGS Mx o fb 2%nat p v0 v1 -> Z.testbit fb 0 = true -> Z.testbit fb 1 = false -> In (p, 64) LB -> 1 <= v1 ->
    op (v0 + 2 ^ 64 * v1) < 2 ^ 128 ->
    PMSTA.base_okA RSEGS AD Mx ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (w0 w1 : Z),
        regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 o ->
        w0 + 2 ^ 64 * w1 = op (v0 + 2 ^ 64 * v1) -> PQATSW2.bdyn_at RSEGS M' o fb 2%nat p w0 w1 ->
        L5CA.ahpres L ar LB FFx spx (PMSPA.pm_scr NETSA.MUL10_H) [(o, 32); (p, 24)] Mx M' ->
        model_rt model model' -> incl LK' LK -> L5CA.amodel_ok Aw model' ->
        ri_inv (HIk D0) LB FFx LK' crx Aw M' (vml_of model') ->
        srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx' R' rx M' model') Kx) ->
    srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx R PC Mx model) Kx.

Lemma ARITH (st : tstate) Aw6 M6 model6 LK6 (fx6 : FPState) R6 (ra : Z) :
  GM [st_D st] (st_bx st) M6 model6 LK6 Aw6 (st_cr st) -> st_ok M6 st -> 0 <= st_val st < 10 ^ 31 ->
  shz M6 12 -> getr R6 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R6 (reg 10) = Z_to_bv 64 (F + 96) -> getr R6 (reg 11) = Z_to_bv 64 yv -> bregs R6 ->
  (forall (fx7 : FPState) R7 (M7 : mem) model7 LK7 Aw7 (st' : tstate),
      GM [st_D st'] (st_bx st') M7 model7 LK7 Aw7 (st_cr st') -> regs_preserved R6 R7 -> st_ok M7 st' -> st_val st' = op (st_val st) -> akept M6 M7 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx7 R7 ra M7 model7) K) ->
