Lemma ADDCALL (d : Z) (st : tstate) Aw6 M6 model6 LK6 (fx6 : FPState) R6 :
  0 <= d <= 9 ->
  GM [st_D st] (st_bx st) M6 model6 LK6 Aw6 (st_cr st) -> st_ok M6 st -> 0 <= st_val st < 10 ^ 31 ->
  shz M6 12 -> getr R6 (reg 1) = Z_to_bv 64 RA_ADD -> getr R6 (reg 10) = Z_to_bv 64 (F + 96) -> getr R6 (reg 11) = Z_to_bv 64 d -> bregs R6 ->
  (forall (fx7 : FPState) R7 (M7 : mem) model7 LK7 Aw7 (st' : tstate),
      GM [st_D st'] (st_bx st') M7 model7 LK7 Aw7 (st_cr st') -> regs_preserved R6 R7 -> st_ok M7 st' -> st_val st' = st_val st + d -> akept M6 M7 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx7 R7 RA_ADD M7 model7) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx6 R6 ADDPC M6 model6) K.
