(* [comment removed for export] *)
Local Ltac stepv Rn tac :=
  match goal with |- MachineOk (mkst (if ?c then ?A else ?B) _ _ _) = _ => change (if c then A else B) with B end;
  match goal with |- MachineOk (mkst (regupd ?Rp ?rd ?v) _ _ _) = _ =>
    replace (regupd Rp rd v) with Rn; [reflexivity| unfold Rn; f_equal; first [reflexivity | tac]]
  | |- ?g => idtac "STEPV-NOMATCH"; idtac g; fail end.
Lemma words_run fx Rx Mx : getr Rx (reg 24) = Z_to_bv 64 nn -> 10 <= nn ->
  exists R', msteps RSEGS (mst fx Rx DHPC Mx) (mst fx R' D1PC Mx)
    /\ (forall j, j <> 10%nat -> j <> 25%nat -> (j < 32)%nat -> getr R' (reg j) = getr Rx (reg j))
