(* [comment removed for export] *)
Definition zregs (t : Z) (Rx : bvmap 5 word) : Prop :=
  bregs Rx /\ getr Rx (reg 18) = Z_to_bv 64 F /\ getr Rx (reg 19) = Z_to_bv 64 (sa + nn) /\ getr Rx (reg 20) = Z_to_bv 64 xo /\ getr Rx (reg 22) = Z_to_bv 64 sa
  /\ getr Rx (reg 23) = Z_to_bv 64 (F + 96) /\ getr Rx (reg 24) = Z_to_bv 64 nn /\ getr Rx (reg 25) = Z_to_bv 64 t.
Definition ZRL : list nat := [2; 3; 4; 8; 9; 21; 26; 27; 18; 19; 20; 22; 23; 24; 25]%nat.
