(* [comment removed for export] *)
Theorem TOBD_OK : forall (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
    (sp r sa nn neg xo : Z) (D : list (list Z)) (RC : list Z),
  ri_inv (HIk D) LBX FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
  PMSPA.entryA AD L ar R M sp r NETSA.TOB_H -> PGSA.ffroomB PQRA.FCM NETSA.TOB_H FF LK -> PMSPA.ffrsA FF sp -> sp mod 16 = 0 ->
  getr R (reg 10) = Z_to_bv 64 sa -> getr R (reg 11) = Z_to_bv 64 nn -> getr R (reg 12) = Z_to_bv 64 neg -> getr R (reg 13) = Z_to_bv 64 xo ->
  (neg = 0 \/ neg = 1) -> HAR.rchain L ar M sp (bv_unsigned (getr R (reg 8))) RC -> bv_unsigned (getr R (reg 8)) <> sp + 8 ->
  0 <= nn <= 31 -> (0 <= sa /\ sa + nn <= 2 ^ 47) -> L5.defined M sa nn -> PMSPA.accA M sa nn -> (nn = 0 \/ PGS.in_blk LBX sa nn \/ PMSPA.aobjA FF sa nn) ->
  (nn = 0 \/ sa + nn <= xo \/ xo + 32 <= sa) -> PMSPA.aobjA FF xo 32 -> xo mod 8 = 0 -> PMSPA.accA M xo 32 -> PQATSS.binl_at RSEGS M xo 0 0%nat 0 0 ->
  PMSTA.base_okA RSEGS AD M -> PMSP.credit_le (PNAETBK.PTD LR r D RC) cr ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (cr' : credit) (rc : Z) (D' : list (list Z)),
      regs_preserved R R' -> getr R' (reg 11) = Z_to_bv 64 rc ->
      ((rc = 0 /\ exists fbx x0 x1, PQATSS.binl_at RSEGS M' xo fbx (PQATSS.wlen x0 x1) x0 x1 /\ Z.testbit fbx 0 = false)
       \/ (rc = 22 /\ PQATSS.binl_at RSEGS M' xo 0 0%nat 0 0)) ->
      L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr NETSA.TOB_H) [(xo, 32)] M M' ->
      PMSP.credit_keep cr cr' (PNAETBK.PTD LR r D RC) (PNAETBK.PTD LR r D' RC) ->
      model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> incl D D' ->
      ri_inv (HIk D') LBX FF LK' cr' Aw' M' (vml_of model') ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K) ->
  forall fx : FPState, srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R N0 M model) K.
